package com.hostelcare.controller;
import com.hostelcare.dto.ApiDtos.*;import com.hostelcare.entity.*;import com.hostelcare.repository.*;import com.hostelcare.service.ComplaintService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.security.Principal;import java.nio.file.*;import java.util.*;
@RestController @RequestMapping("/api/complaints") public class ComplaintController {private final ComplaintService service;private final ComplaintHistoryRepository history;private final ComplaintAttachmentRepository attachments;private final AssignmentRepository assignments;public ComplaintController(ComplaintService s,ComplaintHistoryRepository h,ComplaintAttachmentRepository a,AssignmentRepository as){service=s;history=h;attachments=a;assignments=as;}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,Object> create(@RequestPart("data") @Valid ComplaintRequest req,@RequestPart(value="images",required=false) List<MultipartFile> images,Principal p){return ViewMapper.complaint(service.create(p.getName(),req,images));}
 @PostMapping(consumes=MediaType.APPLICATION_JSON_VALUE) public Map<String,Object> createJson(@Valid @RequestBody ComplaintRequest req,Principal p){return ViewMapper.complaint(service.create(p.getName(),req,List.of()));}
 @GetMapping("/{id}") public Map<String,Object> get(@PathVariable Long id,Principal p){Complaint c=service.get(id,p.getName());Map<String,Object> m=ViewMapper.complaint(c);m.put("history",history.findByComplaintComplaintIdOrderByChangedAtAsc(id).stream().map(h->Map.of("oldStatus",h.oldStatus==null?"":h.oldStatus,"newStatus",h.newStatus,"remarks",h.remarks==null?"":h.remarks,"changedAt",h.changedAt,"updatedBy",h.updatedBy==null?"System":h.updatedBy.name)).toList());m.put("attachments",attachments.findByComplaintComplaintId(id).stream().map(a->Map.of("attachmentId",a.attachmentId,"fileName",a.fileName,"url","/api/complaints/"+id+"/attachments/"+a.attachmentId)).toList());m.put("assignments",assignments.findByComplaintComplaintIdAndActiveTrue(id).stream().map(a->Map.of("staffName",a.staff.name,"staffEmail",a.staff.email,"assignedAt",a.assignedAt)).toList());return m;}
 @GetMapping("/{id}/attachments/{attachmentId}") public ResponseEntity<?> attachment(@PathVariable Long id,@PathVariable Long attachmentId,Principal p){service.get(id,p.getName());ComplaintAttachment a=attachments.findById(attachmentId).filter(x->x.complaint.complaintId.equals(id)).orElseThrow(()->new NoSuchElementException("Attachment not found"));try{Path path=Paths.get(a.filePath);byte[] bytes=Files.readAllBytes(path);String type=Files.probeContentType(path);return ResponseEntity.ok().contentType(MediaType.parseMediaType(type==null?"application/octet-stream":type)).body(bytes);}catch(Exception e){throw new NoSuchElementException("Attachment not found");}}
 @PutMapping("/{id}/close") public Map<String,Object> close(@PathVariable Long id,Principal p){return ViewMapper.complaint(service.updateStatus(id,p.getName(),new StatusRequest("CLOSED","Student confirmed resolution"),false));}
 @PutMapping("/{id}/reopen") public Map<String,Object> reopen(@PathVariable Long id,Principal p){return ViewMapper.complaint(service.updateStatus(id,p.getName(),new StatusRequest("REOPENED","Student requested reopening"),false));}
 @PostMapping("/{id}/feedback") public Map<String,String> feedback(@PathVariable Long id,@Valid @RequestBody FeedbackRequest r,Principal p){service.feedback(id,p.getName(),r);return Map.of("message","Feedback submitted successfully.");}
}
